#!/usr/bin/env node
// Single source of truth: navigation.json. Never edit generated files.
import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const schemaDir = dirname(fileURLToPath(import.meta.url));
const projectDir = resolve(schemaDir, '..');
const schema = JSON.parse(readFileSync(join(schemaDir, 'navigation.json'), 'utf8'));
const allowedIds = new Set(['chat','work','projects','skills','settings']);
if (schema.version !== 1 || !Array.isArray(schema.entries) || schema.entries.length !== allowedIds.size) {
  throw new Error('Unknown navigation schema version or incomplete entries');
}
const entries = schema.entries.slice().sort((a,b) => a.order - b.order);
const seen = new Set();
for (const item of entries) {
  if (!allowedIds.has(item.id) || seen.has(item.id) ||
      !/^[A-Za-z ]{1,36}$/.test(item.label) ||
      !['primary','secondary'].includes(item.placement) ||
      !Number.isInteger(item.order) || item.order < 0 ||
      !item.icons || !['web','qt','android'].every(k => /^[a-z_]+$/.test(item.icons[k]))) {
    throw new Error('Invalid navigation entry: ' + JSON.stringify(item));
  }
  seen.add(item.id);
}
const platformItems = key => entries.map(e => ({
  id:e.id,label:e.label,placement:e.placement,order:e.order,icon:e.icons[key],
}));
const qt = [
  '// GENERATED by meo/ui-schema/generate.mjs. Do not edit.',
  '.pragma library',
  'var navigation = ' + JSON.stringify(platformItems('qt'), null, 2) + ';',
  'function items(placement) { return navigation.filter(function(x) { return x.placement === placement; }); }',
  ''
].join('\n');
const ktItems = platformItems('android').map(x =>
  '    NavItem(' + [x.id,x.label,x.placement,x.icon].map(JSON.stringify).join(', ') +
  ', ' + x.order + ')').join(',\n');
const kotlin = [
  '// GENERATED by meo/ui-schema/generate.mjs. Do not edit.',
  'package org.meo.ai.ui',
  '',
  'data class NavItem(val id: String, val label: String, val placement: String, val icon: String, val order: Int)',
  'object GeneratedNavigation {',
  '  val items: List<NavItem> = listOf(',
  ktItems,
  '  )',
  '  fun entries(placement: String): List<NavItem> = items.filter { it.placement == placement }',
  '}',
  ''
].join('\n');
const web = [
  '// GENERATED by meo/ui-schema/generate.mjs from QwQdoge/meo-ai. Do not edit.',
  'export const uiNavigation = ' + JSON.stringify(platformItems('web'), null, 2) + ' as const;',
  ''
].join('\n');

const check = process.argv.includes('--check');
const targetIndex = process.argv.indexOf('--web-output');
const webOutput = targetIndex >= 0 ? process.argv[targetIndex + 1] : null;
if (targetIndex >= 0 && (!webOutput || webOutput.startsWith('--'))) {
  throw new Error('--web-output needs an existing target directory/path');
}
const files = [
  [join(projectDir, 'app/qml/GeneratedNavigation.js'), qt],
  [join(projectDir, 'android/app/src/main/java/org/meo/ai/ui/GeneratedNavigation.kt'), kotlin],
];
if (webOutput) files.push([resolve(webOutput), web]);
let drift = false;
for (const [file, expected] of files) {
  if (check) {
    if (!existsSync(file) || readFileSync(file, 'utf8') !== expected) {
      console.error('Outdated generated navigation: ' + file);
      drift = true;
    }
  } else {
    writeFileSync(file, expected, 'utf8');
    console.log('Generated ' + file);
  }
}
if (drift) process.exitCode = 1;
